def read(p):return json.loads(p.read_text(encoding='utf8'))
def write(p,x):
 p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
def pin(p,scope):return dict(path=p.relative_to(ROOT).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),passages=[scope])
def source_ids(d,n):return ['R-LRUN-'+k if k in ['C11-ATOMICS','COND'] else 'R-LCON-'+k for k in SOURCES[d][n-1].split()]
